// spec-audit: owner=actionData
pub(crate) fn read_action_action_data(
    c: &mut SchemaReader<'_, '_>,
    el: &Elem,
) -> Res<m::ActionActionData> {
    c.enter()?;
    let mut e = el.clone();
    let mut out = m::ActionActionData {
        id: c.attr(&mut e, "xml:id")?,
        name: c.attr_member(&mut e, "name", false, member_st_data_name)?,
        ref_: c.attr(&mut e, "ref")?,
        ..Default::default()
    };
    c.finish(&e);
    for child in c.children(&e)? {
        if child.in_namespace(NS_IACT) && child.local == "transform" {
            if out.transform.is_some() {
                c.duplicate(&child);
            } else {
                out.transform = Some(Box::new(read_matrix(c, &child)?));
            }
            continue;
        }
        if child.in_namespace(NS_INKML) {
            match child.local.as_str() {
                "trace" => {
                    out.items
                        .push(m::ActionActionDataItem::Trace(Box::new(read_trace(
                            c, &child,
                        )?)));
                    continue;
                }
                "traceView" => {
                    out.items.push(m::ActionActionDataItem::TraceView(Box::new(
                        read_trace_view(c, &child)?,
                    )));
                    continue;
                }
                _ => {}
            }
        }
        c.retained(&child);
    }
    c.leave();
    Ok(out)
}

